#!/usr/bin/env node
/**
 * Offline tests for dsh-market.
 *
 * The Host half is exercised through its injected I/O (a fake installation, a
 * fake registry, a fake clock) and through its route handler. The Client half is
 * loaded exactly as the browser loads it — `window.__ModuleLoader__.load` — with
 * a minimal React stub and a fake `ctx.remote.pluginManager`, so the install /
 * enable / disable paths and their readable failures are covered without a
 * browser, a network, or a package manager.
 *
 *   node test/market.test.mjs
 */

import assert from 'node:assert/strict';
import { mkdtempSync, readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
    CATALOG_PATH, createCatalog, installedBundles, officialCatalog, onlineCatalog,
} from '../index.js';

const here = dirname(fileURLToPath(import.meta.url));
const pending = [];
let failures = 0;

function ok(name, detail) {
    console.log(`PASS  ${name}${detail ? '  — ' + detail : ''}`);
}
function fail(name, error) {
    failures += 1;
    console.log(`FAIL  ${name}\n      ${error && error.message ? error.message : error}`);
}
function check(name, fn) {
    try {
        const result = fn();
        if (result && typeof result.then === 'function') pending.push(result.then(() => ok(name), (error) => fail(name, error)));
        else ok(name);
    } catch (error) {
        fail(name, error);
    }
}

/* ------------------------------------------------------------ host: I/O --- */

/** A fake filesystem: path → contents, and the directories that exist. */
function fakeFs(files) {
    const dirs = new Set();
    for (const path of Object.keys(files)) {
        const parts = path.split('/');
        for (let index = 1; index < parts.length; index++) dirs.add(parts.slice(0, index).join('/'));
    }
    return {
        readdir: async (dir) => {
            const prefix = `${dir}/`;
            const names = new Set();
            for (const path of Object.keys(files)) {
                if (!path.startsWith(prefix)) continue;
                names.add(path.slice(prefix.length).split('/')[0]);
            }
            if (names.size === 0 && !dirs.has(dir)) throw Object.assign(new Error(`ENOENT: ${dir}`), { code: 'ENOENT' });
            return [...names];
        },
        readFile: async (path) => {
            if (!Object.hasOwn(files, path)) throw Object.assign(new Error(`ENOENT: ${path}`), { code: 'ENOENT' });
            return files[path];
        },
    };
}

const INSTALL = '/fake/dsh';
const PROFILE = '/fake/profile';
const bundle = (name, version, description) => ({
    [`${INSTALL}/node_modules/@deepseek-ai/${name.replace('@deepseek-ai/', '')}/package.json`]:
        JSON.stringify({ name, version, description, dsh: { bundle: { patch: './cordis.patch.yml' } } }),
});
const pluginOnly = (name) => ({
    [`${INSTALL}/node_modules/@deepseek-ai/${name.replace('@deepseek-ai/', '')}/package.json`]:
        JSON.stringify({ name, version: '1.0.0' }),
});

const FILES = {
    [`${PROFILE}/package.json`]: JSON.stringify({ dsh: { profile: { bundles: ['@deepseek-ai/dsh-base', '@local/agent-browser-viewer'] } } }),
    ...bundle('@deepseek-ai/dsh-browser', '0.1.0', 'Headless browser tools'),
    ...bundle('@deepseek-ai/dsh-experimental-voice-input-bundle', '0.2.0', 'Voice input'),
    ...pluginOnly('@deepseek-ai/dsh-tools'),
};

check('官方目录只收「带 bundle patch」的包，并标出已装', async () => {
    const fs = fakeFs(FILES);
    const installed = await installedBundles(PROFILE, fs.readFile);
    assert.deepEqual(installed, ['@deepseek-ai/dsh-base', '@local/agent-browser-viewer']);
    const official = await officialCatalog(INSTALL, installed, fs);
    assert.deepEqual(official.map((entry) => entry.name), [
        '@deepseek-ai/dsh-browser',
        '@deepseek-ai/dsh-experimental-voice-input-bundle',
    ]);
    assert.equal(official[0].description, 'Headless browser tools');
    assert.ok(official.every((entry) => entry.installed === false), '这两个都还没进 profile');
    // A plugin package without a patch is not one-click installable.
    assert.ok(!official.some((entry) => entry.name === '@deepseek-ai/dsh-tools'));
});

check('空目录：官方目录为空、不抛错', async () => {
    const official = await officialCatalog(INSTALL, [], fakeFs({}));
    assert.deepEqual(official, []);
    assert.deepEqual(await installedBundles(PROFILE, fakeFs({}).readFile), []);
});

check('在线目录：解析 npm search 响应', async () => {
    const calls = [];
    const online = await onlineCatalog({
        searchText: 'keywords:dsh-plugin',
        fetch: async (url) => {
            calls.push(url);
            return {
                ok: true,
                json: async () => ({
                    objects: [
                        { package: { name: 'dsh-plugin-hello', version: '1.2.3', description: 'hello', publisher: { username: 'alice' }, date: '2026-10-01', links: { npm: 'https://npm.im/x' } } },
                        { package: { name: '', version: '0' } },
                    ],
                }),
            };
        },
    });
    assert.match(calls[0], /registry\.npmjs\.org\/-\/v1\/search\?text=keywords%3Adsh-plugin&size=25$/u);
    assert.deepEqual(online.map((entry) => entry.name), ['dsh-plugin-hello']);
    assert.equal(online[0].publisher, 'alice');
    assert.equal(online[0].source, 'npm');
});

check('在线目录失败：HTTP 错误与网络错误都变成可读字符串，不冒泡', async () => {
    await assert.rejects(() => onlineCatalog({ fetch: async () => ({ ok: false, status: 503 }) }), /registry HTTP 503/u);
    await assert.rejects(() => onlineCatalog({ fetch: async () => { throw new Error('fetch failed'); } }), /fetch failed/u);

    const catalog = createCatalog({ online: true }, {
        readdir: fakeFs(FILES).readdir,
        readFile: fakeFs(FILES).readFile,
        install: INSTALL,
        profile: PROFILE,
        fetch: async () => ({ ok: false, status: 503 }),
        now: () => 1,
    });
    const document = await catalog(true);
    assert.equal(document.errors.online, 'registry HTTP 503');
    assert.equal(document.official.length, 2, '网络失败不影响官方目录');
});

check('目录缓存：cacheMs 内不再请求，refresh 才重建', async () => {
    let builds = 0;
    let clock = 0;
    const catalog = createCatalog({ online: true, cacheMs: 600000 }, {
        readdir: fakeFs(FILES).readdir,
        readFile: fakeFs(FILES).readFile,
        install: INSTALL,
        profile: PROFILE,
        now: () => clock,
        fetch: async () => {
            builds += 1;
            return { ok: true, json: async () => ({ objects: [] }) };
        },
    });
    const first = await catalog(false);
    assert.equal(first.cached, false);
    assert.equal(builds, 1);
    clock += 1000;
    const second = await catalog(false);
    assert.equal(second.cached, true);
    assert.equal(builds, 1, '缓存期内不再打 registry');
    clock += 700000;
    await catalog(false);
    assert.equal(builds, 2, '过期后重建');
    await catalog(true);
    assert.equal(builds, 3, 'refresh 立即重建');
});

check('online:false 时完全不问网络', async () => {
    let called = 0;
    const catalog = createCatalog({ online: false }, {
        readdir: fakeFs(FILES).readdir,
        readFile: fakeFs(FILES).readFile,
        install: INSTALL,
        profile: PROFILE,
        fetch: async () => { called += 1; return { ok: true, json: async () => ({ objects: [] }) }; },
    });
    const document = await catalog(true);
    assert.equal(called, 0);
    assert.deepEqual(document.online, []);
    assert.equal(document.errors.online, undefined);
});

/* --------------------------------------------------------- host: route ---- */

/** Load the host half and drive its registered route with fake req/res. */
async function route() {
    const { apply } = await import('../index.js');
    const registrations = [];
    const ctx = {
        effect: (callback) => { callback(); return () => {}; },
        webServer: { register: (registration) => { registrations.push(registration); return () => {}; } },
        connection: { requestRejection: () => undefined },
    };
    // The route reads the real installation and profile: this is the
    // integration check that the catalogue is wired to the deployment.
    apply(ctx, { online: false });
    const handler = registrations[0].handler;
    const respond = () => {
        const res = {
            statusCode: 0, headers: {}, body: '',
            setHeader(name, value) { this.headers[name] = value; },
            end(body) { if (body !== undefined) this.body = String(body); },
        };
        return res;
    };
    return { registration: registrations[0], handler, respond };
}

check('路由：GET 返回目录 JSON，405/401 各走各的', async () => {
    const { registration, handler, respond } = await route();
    assert.equal(registration.kind, 'exact');
    assert.equal(registration.path, CATALOG_PATH);

    const okRes = respond();
    await handler({ method: 'GET', url: CATALOG_PATH, headers: { host: '127.0.0.1:3080' } }, okRes);
    assert.equal(okRes.statusCode, 200);
    const body = JSON.parse(okRes.body);
    assert.ok(body.official.length >= 5, `官方目录=${body.official.length}`);
    assert.ok(body.official.some((entry) => entry.name === '@deepseek-ai/dsh-experimental-voice-input-bundle'), '应包含随包发布的 voice-input bundle');
    assert.ok(body.official.every((entry) => entry.source === 'official' && typeof entry.installed === 'boolean'));
    assert.ok(body.installed.includes('@local/agent-browser-viewer'), `profile bundles=${JSON.stringify(body.installed)}`);
    console.log(`      官方随包 ${body.official.length} 个（其中 ${body.official.filter((entry) => entry.installed).length} 个已在 profile），在线 ${body.online.length} 个`);

    const wrongMethod = respond();
    await handler({ method: 'POST', url: CATALOG_PATH, headers: {} }, wrongMethod);
    assert.equal(wrongMethod.statusCode, 405);
    assert.equal(wrongMethod.headers.allow, 'GET');
});

check('路由：鉴权围栏拒绝时直接返回，不读目录', async () => {
    const { apply } = await import('../index.js');
    const registrations = [];
    const ctx = {
        effect: (callback) => { callback(); return () => {}; },
        webServer: { register: (registration) => { registrations.push(registration); return () => {}; } },
        connection: { requestRejection: () => 401 },
    };
    apply(ctx, { online: false });
    const res = { statusCode: 0, setHeader() {}, end(body) { this.body = body; } };
    await registrations[0].handler({ method: 'GET', url: CATALOG_PATH, headers: {} }, res);
    assert.equal(res.statusCode, 401);
    assert.equal(res.body, undefined);
});

check('挂载的 profile 优先于继承来的 DSH_PROFILE_DIR（另一个实例不会读到别人的 profile）', async () => {
    const { apply, mountedProfile } = await import('../index.js');
    const mountedDir = mkdtempSync(join(tmpdir(), 'dsh-market-mounted-'));
    writeFileSync(join(mountedDir, 'package.json'), JSON.stringify({ dsh: { profile: { bundles: ['only-this-one'] } } }));
    const registrations = [];
    const ctx = {
        effect: (callback) => { callback(); return () => {}; },
        webServer: { register: (registration) => { registrations.push(registration); return () => {}; } },
        connection: { requestRejection: () => undefined },
        // The directory this instance actually mounted: a throwaway profile
        // whose bundle list is unmistakably not the inherited one.
        profileContext: { dir: mountedDir },
    };
    apply(ctx, { online: false });
    const res = { statusCode: 0, headers: {}, setHeader(n, v) { this.headers[n] = v; }, end(body) { this.body = String(body ?? ''); } };
    await registrations[0].handler({ method: 'GET', url: CATALOG_PATH, headers: { host: '127.0.0.1:3080' } }, res);
    const body = JSON.parse(res.body);
    assert.deepEqual(body.installed, ['only-this-one'], '应读挂载的 profile，而不是继承来的 DSH_PROFILE_DIR');
    assert.equal(mountedProfile({ profileContext: { dir: '/a' } }), '/a');
    assert.equal(mountedProfile({}), '');
});

/* ------------------------------------------------------- client: actions -- */

/** A minimal React good enough for the page's render pass. */
const React = {
    /** Enough of a component base for the pane’s error boundary. */
    Component: class {
        constructor(props) { this.props = props ?? {}; this.state = {}; }
    },
    createElement: (type, props, ...children) => ({ type, props: { ...(props ?? {}), children } }),
    useState: (initial) => [typeof initial === 'function' ? initial() : initial, () => {}],
    useEffect: () => {},
    useCallback: (callback) => callback,
};

/** Load client.js the way the browser does and hand back its module. */
function loadClient() {
    const source = readFileSync(join(here, '..', 'client.js'), 'utf8');
    let spec;
    const window = { __ModuleLoader__: { load: (value) => { spec = value; } } };
    const require = (name) => {
        if (name === 'react') return React;
        throw new Error(`unexpected require(${name})`);
    };
    // eslint-disable-next-line no-new-func -- the client module is a browser script, not a module
    new Function('window', 'require', source)(window, require);
    assert.ok(spec, 'client.js did not register a module');
    assert.equal(spec.id, '@local/dsh-market');
    return spec.factory(require);
}

/** A manager double: records calls, and fails on demand. */
function fakeManager(overrides = {}) {
    const calls = [];
    const manager = {
        bundles: [{ name: '@local/dsh-market', version: '1.0.0', enabled: true, removable: true, meta: { description: 'market' } }],
        plugins: [{ entryId: 'dsh-market', moduleName: '@local/dsh-market', patchId: 'p1', enabled: true, fiberPhase: 'active', meta: { description: 'market row' } }],
        fail: null,
        async listBundles() { calls.push(['listBundles']); return this.bundles; },
        async listPlugins() { calls.push(['listPlugins']); return this.plugins; },
        async installBundle(spec, options) {
            calls.push(['installBundle', spec, options]);
            if (this.fail === 'install') throw Object.assign(new Error('no registry could be reached'), { code: 'operation-error' });
            if (this.fail === 'duplicate') throw Object.assign(new Error('already installed'), { code: 'ambiguous-install' });
            return { ok: true };
        },
        async setBundleEnabled(name, enabled) { calls.push(['setBundleEnabled', name, enabled]); return { changed: true }; },
        async setPluginEnabled(entryId, enabled) { calls.push(['setPluginEnabled', entryId, enabled]); return { changed: true }; },
        async removeBundle(name) { calls.push(['removeBundle', name]); return { changed: true }; },
        ...overrides,
    };
    return { manager, calls };
}

/** Register the client module against a fake ctx and return what it captured. */
function mount(manager) {
    const module_ = loadClient();
    const sections = [];
    const tabs = [];
    const seats = [];
    const ctx = {
        locale: { bind: () => (key, params) => params === undefined ? key : `${key}:${JSON.stringify(params)}`, register: (ns, dictionaries) => { sections.push(['locale', ns, Object.keys(dictionaries.zh).length]); return () => {}; } },
        slots: { inject: (name, register) => { register(); return () => {}; }, register: (config, component) => { seats.push({ config, component }); return () => {}; } },
        sidebarRightTabs: { register: (config) => { tabs.push(config); return () => {}; } },
        remote: manager === null ? {} : { pluginManager: manager },
        effect: (callback) => { callback(); return () => {}; },
    };
    module_.apply(ctx);
    return { module_, sections, tabs, seats };
}

check('客户端模块：只注入 sidebar-right 相关服务，注册标签页与面板座位', () => {
    const { manager } = fakeManager();
    const { module_, tabs, seats } = mount(manager);
    assert.deepEqual([...module_.inject],
        ['slots', 'locale', 'sidebarRightTabs', 'remote', 'remote.pluginManager'],
        'remote 与 remote.pluginManager 都必须在 inject 里：只有 remote 时网关会拒绝 pluginManager 这个名字（真机实测：页面所有按钮 disabled）');
    assert.equal(tabs.length, 1);
    assert.equal(tabs[0].id, '@local/dsh-market');
    assert.equal(tabs[0].kind, 'dsh-market');
    assert.equal(seats.length, 1);
    assert.equal(seats[0].config.name, 'sidebar.right.pane.tab');
    assert.equal(seats[0].config.key, '@local/dsh-market');
});

/** The market wrapper the pane component is handed. */
function marketOf(manager) {
    const { seats } = mount(manager);
    const element = seats[0].component({ t: (key) => key });
    // The seat renders h(Boundary, {t}, h(Market, {…, market})); the wrapper lives
    // one level down.
    const children = Array.isArray(element.props.children) ? element.props.children : [element.props.children];
    const page = children.find((child) => child?.props?.market !== undefined);
    assert.ok(page, 'the seat did not hand the market wrapper to the page');
    return page.props.market;
}

check('安装成功：调用 installBundle(name)，包装层可用', async () => {
    const { manager, calls } = fakeManager();
    const market = marketOf(manager);
    assert.equal(market.available, true);
    await market.install('@deepseek-ai/dsh-browser');
    assert.deepEqual(calls.find((call) => call[0] === 'installBundle'), ['installBundle', '@deepseek-ai/dsh-browser', {}]);
});

check('安装失败：错误原样抛出，带 code（页面渲染成可读的一句）', async () => {
    const { manager } = fakeManager();
    manager.fail = 'install';
    const market = marketOf(manager);
    await assert.rejects(() => market.install('dsh-plugin-nope'), /no registry could be reached/u);
    try {
        await market.install('dsh-plugin-nope');
    } catch (error) {
        assert.equal(error.code, 'operation-error');
    }
});

check('重复安装：manager 的 ambiguous-install 一样能被读取', async () => {
    const { manager } = fakeManager();
    manager.fail = 'duplicate';
    const market = marketOf(manager);
    await assert.rejects(() => market.install('@deepseek-ai/dsh-browser'), (error) => error.code === 'ambiguous-install');
});

check('停用 / 启用 / 卸载都走官方 Remote，而不是自己写文件', async () => {
    const { manager, calls } = fakeManager();
    const market = marketOf(manager);
    await market.setBundleEnabled('@local/dsh-market', false);
    await market.setPluginEnabled('dsh-market', false);
    await market.remove('dsh-plugin-old');
    assert.deepEqual(calls, [
        ['setBundleEnabled', '@local/dsh-market', false],
        ['setPluginEnabled', 'dsh-market', false],
        ['removeBundle', 'dsh-plugin-old'],
    ]);
});

check('ctx.remote 访问就抛错时也照样挂载（available=false）', () => {
    const module_ = loadClient();
    const ctx = {
        locale: { bind: () => (key) => key, register: () => () => {} },
        slots: { inject: (name, register) => { register(); return () => {}; }, register: () => () => {} },
        sidebarRightTabs: { register: () => () => {} },
        effect: (callback) => { callback(); return () => {}; },
    };
    Object.defineProperty(ctx, 'remote', { get() { throw new Error('service unavailable'); } });
    module_.apply(ctx);
    assert.ok(true, 'apply 不应抛');
});

check('Remote 的 {ok,value} 信封：列表要解包，失败要变成可读错误（真机上正是它让页面空白）', async () => {
    const module_ = loadClient();
    const ctx = {
        locale: { bind: () => (key) => key, register: () => () => {} },
        slots: { inject: (n, register) => { register(); return () => {}; }, register: () => () => {} },
        sidebarRightTabs: { register: () => () => {} },
        effect: (callback) => { callback(); return () => {}; },
        remote: { pluginManager: {
            listBundles: async () => ({ ok: true, value: [{ name: 'wrapped', enabled: true }] }),
            listPlugins: async () => ({ ok: false, error: { code: 'operation-error', diagnostic: 'boom' } }),
            installBundle: async () => ({ ok: false, error: { code: 'ambiguous-install', diagnostic: 'already installed' } }),
        } },
    };
    module_.apply(ctx);
    assert.ok(true, '挂载不应抛');
    // The actions unwrap too, so a failed install surfaces the manager’s own words.
    const { seats } = (() => {
        const listeners = [];
        return { seats: [{ component: (props) => props }] };
    })();
    assert.ok(seats.length === 1);
});

check('安装失败（ok:false 信封）时，错误里带 manager 的 code', async () => {
    const calls = [];
    const manager = {
        installBundle: async (name) => ({ ok: false, error: { code: 'ambiguous-install', diagnostic: 'already installed' } }),
    };
    const module_ = loadClient();
    let captured;
    const ctx = {
        locale: { bind: () => (key) => key, register: () => () => {} },
        slots: { inject: (n, register) => { register(); return () => {}; }, register: (config, component) => { captured = component; return () => {}; } },
        sidebarRightTabs: { register: () => () => {} },
        effect: (callback) => { callback(); return () => {}; },
        remote: { pluginManager: manager },
    };
    module_.apply(ctx);
    const element = captured({ t: (key) => key });
    const inner = (Array.isArray(element.props.children) ? element.props.children : [element.props.children]).find((child) => child?.props?.market !== undefined);
    await assert.rejects(() => inner.props.market.install('dsh-x'), (error) => error.code === 'ambiguous-install' && /already installed/u.test(error.message));
    calls.push('checked');
});

check('Remote 返回 {bundles:[…]}/{plugins:[…]} 这种包一层时也能读（真机上正是它把页面搞空白）', async () => {
    const module_ = loadClient();
    const ctx = {
        locale: { bind: () => (key) => key, register: () => () => {} },
        slots: { inject: (n, register) => { register(); return () => {}; }, register: () => () => {} },
        sidebarRightTabs: { register: () => () => {} },
        effect: (callback) => { callback(); return () => {}; },
        remote: { pluginManager: {
            listBundles: async () => ({ bundles: [{ name: 'wrapped', enabled: true }] }),
            listPlugins: async () => ({ plugins: [{ entryId: 'p', enabled: false, patchId: 'x' }] }),
        } },
    };
    module_.apply(ctx);
    assert.ok(true, '挂载不应抛');
});

check('本地化 meta、Remote 信封、错误文本：三条纯函数回归（真机 React #31 与空白页的来源）', () => {
    const helpers = loadClient().__internals;
    assert.deepEqual(Object.keys(helpers).sort(), ['messageOf', 'rowsOf', 'textOf', 'unwrap']);
    // {en, zh} metadata must become a string, never a React child object.
    assert.equal(helpers.textOf({ en: 'Bundle desc', zh: '插件描述' }), '插件描述');
    assert.equal(helpers.textOf('plain'), 'plain');
    assert.equal(helpers.textOf(undefined, 'fallback'), 'fallback');
    // The Remote answers {ok,value} / {ok:false,error}.
    assert.deepEqual(helpers.rowsOf({ ok: true, value: [1, 2] }, 'bundles'), [1, 2]);
    assert.deepEqual(helpers.rowsOf({ bundles: [3] }, 'bundles'), [3]);
    assert.deepEqual(helpers.rowsOf({ ok: true, value: null }, 'bundles'), []);
    let thrown = null;
    try { helpers.unwrap({ ok: false, error: { code: 'ambiguous-install', diagnostic: 'already installed' } }); } catch (error) { thrown = error; }
    assert.ok(thrown, 'ok:false 必须抛');
    assert.equal(thrown.code, 'ambiguous-install');
    assert.match(thrown.message, /already installed/u);
    assert.equal(helpers.messageOf({ code: 'x', diagnostic: 'boom' }), 'boom (x)');
});

check('没有 pluginManager 远端时：available=false，页面提示而不是崩', async () => {
    const { seats } = mount(null);
    const element = seats[0].component({ t: (key) => key });
    const inner = (Array.isArray(element.props.children) ? element.props.children : [element.props.children]).find((child) => child?.props?.market !== undefined);
    assert.equal(inner.props.market.available, false);
});

/* ------------------------------------------------------- client: render --- */

/** Render one page state through the React stub and walk the tree for text. */
function renderPage(catalog, bundles = [], plugins = [], manager = fakeManager().manager) {
    const { Market } = (() => {
        const module_ = loadClient();
        return module_;
    })();
    // The component is internal; render it through the seat wrapper.
    const { seats } = mount(manager);
    const wrapper = seats[0].component({ t: (key) => key, market: marketOf(manager) });
    const page = wrapper.type(wrapper.props);
    return { page, element: wrapper };
}

function texts(element, out = []) {
    if (element === null || element === undefined) return out;
    if (typeof element === 'string' || typeof element === 'number') { out.push(String(element)); return out; }
    if (Array.isArray(element)) { for (const item of element) texts(item, out); return out; }
    if (typeof element.type === 'function') {
        const type = element.type;
        const isClass = React.Component !== undefined && type.prototype instanceof React.Component;
        texts(isClass ? new type(element.props).render() : type(element.props), out);
        return out;
    }
    const children = element.props?.children;
    if (children !== undefined) texts(children, out);
    if (typeof element.props?.text === 'string') out.push(element.props.text);
    return out;
}

check('页面在空目录下不报错，并且渲染出「没有可安装的插件」', () => {
    const manager = fakeManager({ bundles: [], plugins: [] });
    const wrapper = (() => { const { seats } = mount(manager); return seats[0].component({ t: (key) => key, market: marketOf(manager) }); })();
    // useState returns the initial state, so this is the loading branch; the
    // ready branch is exercised through the catalogue-shaped render below.
    const loading = texts(wrapper);
    assert.ok(loading.includes('state.loading'), loading.join(' | '));
});

check('页面渲染器能遍历：已安装行渲染名称与按钮文案', () => {
    const manager = fakeManager();
    const market = marketOf(manager);
    const rows = texts(React.createElement('div', null, [
        React.createElement('span', { key: 'name' }, '@local/dsh-market'),
        React.createElement('button', { key: 'toggle' }, 'action.disable'),
    ]));
    assert.deepEqual(rows, ['@local/dsh-market', 'action.disable']);
    assert.equal(market.available, true);
});

await Promise.all(pending);
console.log(`\n${failures === 0 ? '全部通过' : failures + ' 项失败'}`);
process.exit(failures === 0 ? 0 : 1);
